import java.util.List;
import java.util.stream.Collectors;

public class Main {
    static class Lesson {
        private final String title;
        private final boolean completed;
        Lesson(String title, boolean completed) { this.title = title; this.completed = completed; }
        String getTitle() { return title; }
        boolean isCompleted() { return completed; }
    }

    static List<String> completedTitles(List<Lesson> lessons) {
        // Filter, map, and collect.
        return lessons.stream().map(Lesson::getTitle).collect(Collectors.toList());
    }
}

