import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class Main {
    static class Lesson {
        private final String course;
        Lesson(String course) { this.course = course; }
        String getCourse() { return course; }
    }

    static Map<String, List<Lesson>> groupByCourse(List<Lesson> lessons) {
        // Collect lessons under their course name.
        return lessons.stream().collect(Collectors.groupingBy(Lesson::getCourse));
    }
}
